    group_id uuid NOT NULL,
    user_id uuid NOT NULL,
    ref_id bigint,
    night timestamp with time zone NOT NULL,
    mime text NOT NULL,
    bytes bytea,
    size integer DEFAULT 0 NOT NULL,
    w integer DEFAULT 0 NOT NULL,
    h integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reveal_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL
);

CREATE TABLE public.spel_inputs (
    room_id uuid NOT NULL,
    game_no integer NOT NULL,
    round integer NOT NULL,
    user_id uuid NOT NULL,
    val jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.spel_players (
    room_id uuid NOT NULL,
    user_id uuid NOT NULL,
    k text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'in'::text NOT NULL,
    ord integer DEFAULT 0 NOT NULL,
    score integer DEFAULT 0 NOT NULL,
    hand integer[] DEFAULT '{}'::integer[] NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    seen_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.spel_rooms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    group_id uuid NOT NULL,
    game text DEFAULT 'kort'::text NOT NULL,
    phase text DEFAULT 'lobby'::text NOT NULL,
    round integer DEFAULT 0 NOT NULL,
    goal integer DEFAULT 5 NOT NULL,
    game_no integer DEFAULT 0 NOT NULL,
    pub jsonb DEFAULT '{}'::jsonb NOT NULL,
    sec jsonb DEFAULT '{}'::jsonb NOT NULL,
    v integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '03:00:00'::interval) NOT NULL,
    closed boolean DEFAULT false NOT NULL
);

CREATE TABLE public.squad_checks (
    group_id uuid NOT NULL,
